            descriptionLongue = "Elrathia kingii é um pequeno trilobite do Câmbrico médio, extraído em quantidades consideráveis dos xistos da formação de Wheeler, no Utah — um jazigo tão produtivo que fornece a quase totalidade dos trilobites vendidos no comércio mundial. A sua segmentação tricéfala característica (cabeça, tórax, pigídio) faz dele um excelente exemplar pedagógico para compreender a anatomia deste grupo de artrópodes extinto desde o final do Pérmico.",
            interetJoaillerie = "Fraco: essencialmente coleção, por vezes montado em bruto em pendente protegido"
        ),
        "fossile-trilobite-phacops" to FossileTranslation(
