            descriptionLongue = "O megalodonte, tubarão gigante extinto há cerca de 3,6 milhões de anos, podia atingir 15 a 18 metros de comprimento. Os seus dentes triangulares maciços, serrilhados como os do atual tubarão-branco mas muito maiores, mineralizaram-se no sedimento adquirindo tonalidades variadas consoante os jazigos. As mais belas peças, simétricas e sem desgaste, atingem preços elevados tanto em coleção como em joalharia bruta.",
            interetJoaillerie = "Elevado: pendentes em bruto engastados em garra, muito procurados em joalharia decorativa"
        ),
        "fossile-os-dinosaure-gembone" to FossileTranslation(
