            descriptionCourte = "Um osso de dinossauro inteiramente substituído molécula a molécula por ágata colorida.",
            descriptionLongue = "Em certos jazigos do Jurássico americano, os ossos de dinossauros soterrados sofreram uma silicificação completa: a matéria óssea original foi dissolvida e progressivamente substituída por sílica colorida, preservando fielmente a estrutura celular porosa do osso ao mesmo tempo que a transformava em ágata polível. O resultado, apelidado «gembone» pelos lapidários, combina o valor científico de um autêntico fóssil de dinossauro com o apelo estético de uma pedra semipreciosa de padrões únicos.",
            interetJoaillerie = "Elevado: cabochões muito procurados, padrão celular único impossível de imitar"
        ),
        "fossile-poisson-green-river" to FossileTranslation(
            nom = "Peixe fóssil de Green River",
            descriptionCourte = "Cardumes inteiros de pequenos peixes fixados num calcário lacustre de finura excecional.",
            descriptionLongue = "O antigo Lago Fóssil do Wyoming preservou, em sedimentos finamente estratificados, dezenas de milhares de peixes de água doce num estado de conservação excecional — escamas, barbatanas e por vezes conteúdo estomacal intactos. A formação de Green River é hoje um dos jazigos de vertebrados fósseis mais prolíficos do mundo, explorado a céu aberto e vendido em lajes serradas para decoração.",
            interetJoaillerie = "Moderado: lajes emolduradas, objetos de decoração e não joias"
