            descriptionCourte = "O marfim de um gigante extinto da última era glacial, libertado pelo degelo do pergelissolo siberiano.",
            descriptionLongue = "O aquecimento progressivo do pergelissolo siberiano liberta todos os anos presas de mamutes-lanosos, por vezes notavelmente conservadas após dezenas de milhares de anos de soterramento no gelo. Este comércio, legal e regulamentado ao contrário do marfim de elefante moderno, alimenta escultores e joalheiros com um material de textura e grão próximos do marfim vivo, por vezes realçado com tonalidades azul-esverdeadas espetaculares devidas a uma mineralização superficial por fosfato de ferro (vivianite).",
            interetJoaillerie = "Elevado: esculturas, joias, incrustações — comércio legal enquadrado, ao contrário do marfim de elefante atual"
        ),
        "fossile-bois-petrifie" to FossileTranslation(
            nom = "Madeira petrificada",
            descriptionCourte = "Um tronco de árvore inteiro transformado em pedra, anel de crescimento a anel de crescimento, por infiltração de sílica.",
            descriptionLongue = "Quando um tronco cai e rapidamente fica soterrado num sedimento saturado em sílica, a água rica em silicatos infiltra-se progressivamente na estrutura celular da madeira e substitui-a, fibra a fibra, antes que a decomposição a apague. O resultado conserva a textura, os anéis de crescimento e por vezes até os insetos que escavaram a casca, ao mesmo tempo que adquire a dureza e o polimento da ágata — daí a sua popularidade tanto em joalharia como em mobiliário decorativo de grande porte.",
            interetJoaillerie = "Elevado: cabochões e joias, também muito procurada em decoração (tabuleiros, tampos de mesa)"
        ),
        "fossile-fougere" to FossileTranslation(
            nom = "Feto fóssil",
            descriptionCourte = "A delicada impressão carbonosa de um feto das imensas florestas pantanosas do Carbónico.",
            descriptionLongue = "Os vastos pântanos florestais do Carbónico, na origem da maioria dos jazigos de carvão atuais, deixaram nos seus xistos argilosos inúmeras impressões de fetos e de fetos-com-sementes, preservadas sob a forma de uma fina película de carbono. Estas placas, obtidas clivando a rocha ao longo do plano da folha fossilizada, revelam nervuras de uma finura notável para vegetais com mais de 300 milhões de anos.",
            interetJoaillerie = "Fraco: essencialmente coleção e decoração de parede emoldurada"
