            descriptionCourte = "A resina fossilizada de florestas de coníferas desaparecidas, a gema orgânica mais antiga da joalharia humana.",
            descriptionLongue = "O âmbar báltico formou-se há cerca de 44 milhões de anos a partir da resina de coníferas gigantes, hoje extintas, cujas florestas cobriam o norte da Europa. Arrastado pelos cursos de água e depois lançado nas praias do mar Báltico após as tempestades, é trabalhado e comercializado pela humanidade desde a Idade do Bronze — as rotas comerciais do âmbar contam-se entre as mais antigas vias de troca documentadas na Europa.",
            interetJoaillerie = "Elevado: joalharia tradicional do norte da Europa desde a Idade do Bronze"
        ),
        "fossile-ambre-inclusion" to FossileTranslation(
            nom = "Âmbar com inclusão de inseto",
            descriptionCourte = "Um mosquito, uma formiga ou uma flor fixados para a eternidade numa gota de resina transformada em pedra.",
            descriptionLongue = "O âmbar dominicano, mais recente e geralmente mais transparente que o âmbar báltico, deve a sua fama à riqueza excecional das suas inclusões: insetos, aranhas, pequenas flores e até, ocasionalmente, pequenos vertebrados encontram-se aprisionados com um luxo de detalhes que tornou este fóssil célebre muito além dos círculos de coleccionadores, popularizado nomeadamente pela ficção em torno do ADN preservado em âmbar.",
            interetJoaillerie = "Elevado: cada inclusão é única, forte valor acrescentado em joalharia de coleção"
        ),
        "fossile-copal" to FossileTranslation(
            nom = "Copal",
            descriptionCourte = "O estádio «adolescente» do âmbar: uma resina fóssil demasiado jovem para ter polimerizado totalmente.",
            descriptionLongue = "O copal é uma resina vegetal que ainda não completou a lenta polimerização química que, ao longo de milhões de anos, transforma uma resina em verdadeiro âmbar. Mais macio, mais solúvel em solventes e frequentemente mais transparente, é por vezes vendido abusivamente como âmbar — um teste simples com acetona (que torna o copal pegajoso à superfície, sem efeito sobre o âmbar verdadeiro) permite distingui-los.",
            interetJoaillerie = "Moderado: joalharia artesanal local, a distinguir claramente do âmbar numa ficha de venda"
        ),
        "fossile-corail-agatise" to FossileTranslation(
            nom = "Coral fóssil agatizado",
            descriptionCourte = "Um recife de coral inteiro transformado em ágata, cada pólipo fixado numa flor de sílica.",
            descriptionLongue = "Na Flórida, antigos recifes de coral ficaram silicificados por águas subterrâneas ricas em sílica, sendo cada pólipo de coral fielmente substituído por calcedónia, conservando a sua estrutura radiada característica. Uma vez cortado e polido, o resultado evoca padrões florais naturais tão regulares que por vezes se confunde com uma criação artificial — foi designado pedra oficial do Estado da Flórida em 1979.",
            interetJoaillerie = "Elevado: cabochões de padrões florais únicos, apreciados em joalharia regional e internacional"
        ),
        "fossile-oursin" to FossileTranslation(
            nom = "Ouriço-do-mar fóssil",
            descriptionCourte = "A carapaça calcária de simetria perfeita de um ouriço-do-mar, usada durante muito tempo como talismã.",
            descriptionLongue = "As carapaças (conchas) de ouriços-do-mar fósseis, com a sua característica simetria radiada de cinco braços, encontram-se em abundância nos calcários cretácicos da Europa e do Norte de África. Apelidadas «pães de fada» ou «pedras de São Pedro» no folclore europeu, eram tradicionalmente guardadas como amuleto ou proteção do lar muito antes de serem estudadas cientificamente.",
            interetJoaillerie = "Fraco a moderado: usado tradicionalmente como pendente em bruto («pedra de São Pedro» ou «pão de fada» na Europa)"
        ),
        "fossile-crinoide" to FossileTranslation(
            nom = "Crinoide (entroque)",
            descriptionCourte = "Os anéis calcários empilhados do caule de um «lírio-do-mar», um equinoderme fixo e não uma planta.",
            descriptionLongue = "Apesar do seu nome enganador de «lírio-do-mar», o crinoide é um animal equinoderme aparentado com o ouriço-do-mar e a estrela-do-mar, fixo ao fundo marinho por um longo caule articulado. Este caule, composto por anéis calcários empilhados como moedas, desarticula-se facilmente após a morte do animal e encontra-se em abundância em certos calcários, formando aquilo a que os geólogos chamam um calcário entrocal uma vez polido em laje.",
            interetJoaillerie = "Moderado: lajes e objetos decorativos e não joias, por vezes cabochões para os caules isolados"
        ),
        "fossile-stromatolite" to FossileTranslation(
            nom = "Estromatólito fóssil",
            descriptionCourte = "Os vestígios de vida mais antigos conhecidos na Terra, construídos camada a camada por colónias de bactérias.",
            descriptionLongue = "Os estromatólitos não são os restos de um organismo individual, mas sim estruturas sedimentares laminadas, construídas pacientemente camada após camada por colónias de cianobactérias que aprisionam o sedimento e precipitam carbonato de cálcio. Alguns jazigos australianos contam-se entre os vestígios de vida mais antigos identificados na Terra, com mais de 3,4 mil milhões de anos — um testemunho direto dos primeiríssimos ecossistemas do planeta, hoje polido em lajes decorativas pelo seu padrão concêntrico único.",
            interetJoaillerie = "Fraco a moderado: lajes decorativas, cabochões ocasionais para as variedades silicificadas"
        ),
        "fossile-belemnite" to FossileTranslation(
            nom = "Belemnite",
            descriptionCourte = "O «rostro» fossilizado de uma lula pré-histórica, longamente confundido no folclore com uma pedra de raio.",
            descriptionLongue = "O que se encontra fossilizado não é o animal inteiro, mas sim o seu rostro, uma estrutura calcária interna rígida que servia de contrapeso e sustentação ao corpo mole do cefalópode, primo extinto das lulas atuais. A sua forma cónica e alongada, frequentemente confundida pelo folclore popular europeu com uma «pedra de raio» caída do céu, faz dela um fóssil facilmente reconhecível mesmo por não especialistas.",
            interetJoaillerie = "Fraco: coleção, pendentes em bruto ocasionais"
        )
